window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a34f2e28c559e82f"]={"versions": [{"id": "FIG-a34f2e28c559e82f", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von VFB-Timing-Ereignissen (Virtual Function Bus Events) innerhalb der AUTOSAR Timing Extensions (TPS Adaptive Platform Timing Extensions). Das Metamodell definiert die Spezialisierungshierarchie und Referenzierungsstrukturen für timingrelevante Kommunikationsereignisse auf VFB-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>TimingDescription</code> / <code>TimingDescriptionEvent</code>: Abstrakte Basiselemente der AUTOSAR-Timing-Beschreibung.</li>\n<li><code>TDEventVfb</code>: Abstrakte Spezialisierung von <code>TimingDescriptionEvent</code> für Ereignisse im Kontext des Virtual Function Bus.</li>\n<li><code>TDEventVfbReference</code>: Konkretes VFB-Timing-Event, das über die gerichtete Assoziation <code>+referencedTDEventVfb</code> mit Kardinalität <code>1</code> genau ein übergeordnetes oder anderes <code>TDEventVfb</code> referenziert.</li>\n<li><code>TDEventVfbPort</code>: Abstrakte Spezialisierung von <code>TDEventVfb</code> für portbezogene Ereignisse mit dem Attribut <code>+ isExternal: Boolean</code> (gekennzeichnet zur Spezifikation, ob das Ereignis extern sichtbar bzw. über Systemgrenzen hinweg relevant ist). Es besitzt eine gerichtete Referenz <code>+port</code> mit Multiplizität <code>0..1</code> auf ein <code>PortPrototype</code> (stereotypisiert als <code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>).</li>\n<li>Konkrete Spezialisierungen von <code>TDEventVfbPort</code>:</li>\n<li><code>TDEventVariableDataPrototype</code>: Timing-Ereignisse bezogen auf Datenübertragungen von Variablen-Datenprototypen (Sender-Receiver-Kommunikation).</li>\n<li><code>TDEventOperation</code>: Timing-Ereignisse bezogen auf Client-Server-Operationen.</li>\n<li><code>TDEventModeDeclaration</code>: Timing-Ereignisse bezogen auf Modusumschaltungen und Modusdeklarationen.</li>\n<li><code>TDEventTrigger</code>: Timing-Ereignisse bezogen auf externe oder interne Trigger.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Zur Laufzeit bzw. in der Timing-Analyse repräsentieren Instanzen der konkreten Subklassen Zeitpunkte des Auftretens von VFB-Interaktionen (z. B. Senden/Empfangen von Daten, Operationsaufrufe, Moduswechsel, Trigger). <code>TDEventVfbReference</code> erlaubt dabei die Wiederverwendung oder Delegation bestehender VFB-Event-Definitionen, während <code>isExternal</code> kennzeichnet, ob die Interaktion über einen ECU- oder Partitions-externen Port erfolgt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Modellierungsgrundlage für Timing-Constraints auf VFB-Ebene. Bei der Instanziierung von <code>TDEventVfbPort</code>-Subklassen muss die Referenz <code>+port</code> bei komponentenübergreifender Relevanz auf einen existierenden <code>PortPrototype</code> aufgelöst werden (Kardinalität <code>0..1</code>). Das Attribut <code>isExternal</code> steuert die Zuordnung zu ECU-externen Netzwerkpfaden versus rein interner VFB-Kommunikation. <code>TDEventVfbReference</code> erzwingt eine strikte 1:1-Referenzierung auf ein Ziel-<code>TDEventVfb</code>.</p>"}, {"id": "FIG-2684fed4f6e0d0e4", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation von VFB-Timing-Ereignissen (Virtual Function Bus Events) innerhalb der AUTOSAR Timing Extensions (TPS Adaptive Platform Timing Extensions). Das Metamodell definiert die Spezialisierungshierarchie und Referenzierungsstrukturen für timingrelevante Kommunikationsereignisse auf VFB-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>TimingDescription</code> / <code>TimingDescriptionEvent</code>: Abstrakte Basiselemente der AUTOSAR-Timing-Beschreibung.</li>\n<li><code>TDEventVfb</code>: Abstrakte Spezialisierung von <code>TimingDescriptionEvent</code> für Ereignisse im Kontext des Virtual Function Bus.</li>\n<li><code>TDEventVfbReference</code>: Konkretes VFB-Timing-Event, das über die gerichtete Assoziation <code>+referencedTDEventVfb</code> mit Kardinalität <code>1</code> genau ein übergeordnetes oder anderes <code>TDEventVfb</code> referenziert.</li>\n<li><code>TDEventVfbPort</code>: Abstrakte Spezialisierung von <code>TDEventVfb</code> für portbezogene Ereignisse mit dem Attribut <code>+ isExternal: Boolean</code> (gekennzeichnet zur Spezifikation, ob das Ereignis extern sichtbar bzw. über Systemgrenzen hinweg relevant ist). Es besitzt eine gerichtete Referenz <code>+port</code> mit Multiplizität <code>0..1</code> auf ein <code>PortPrototype</code> (stereotypisiert als <code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>).</li>\n<li>Konkrete Spezialisierungen von <code>TDEventVfbPort</code>:</li>\n<li><code>TDEventVariableDataPrototype</code>: Timing-Ereignisse bezogen auf Datenübertragungen von Variablen-Datenprototypen (Sender-Receiver-Kommunikation).</li>\n<li><code>TDEventOperation</code>: Timing-Ereignisse bezogen auf Client-Server-Operationen.</li>\n<li><code>TDEventModeDeclaration</code>: Timing-Ereignisse bezogen auf Modusumschaltungen und Modusdeklarationen.</li>\n<li><code>TDEventTrigger</code>: Timing-Ereignisse bezogen auf externe oder interne Trigger.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagrammelemente. Zur Laufzeit bzw. in der Timing-Analyse repräsentieren Instanzen der konkreten Subklassen Zeitpunkte des Auftretens von VFB-Interaktionen (z. B. Senden/Empfangen von Daten, Operationsaufrufe, Moduswechsel, Trigger). <code>TDEventVfbReference</code> erlaubt dabei die Wiederverwendung oder Delegation bestehender VFB-Event-Definitionen, während <code>isExternal</code> kennzeichnet, ob die Interaktion über einen ECU- oder Partitions-externen Port erfolgt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Modellierungsgrundlage für Timing-Constraints auf VFB-Ebene. Bei der Instanziierung von <code>TDEventVfbPort</code>-Subklassen muss die Referenz <code>+port</code> bei komponentenübergreifender Relevanz auf einen existierenden <code>PortPrototype</code> aufgelöst werden (Kardinalität <code>0..1</code>). Das Attribut <code>isExternal</code> steuert die Zuordnung zu ECU-externen Netzwerkpfaden versus rein interner VFB-Kommunikation. <code>TDEventVfbReference</code> erzwingt eine strikte 1:1-Referenzierung auf ein Ziel-<code>TDEventVfb</code>.</p>"}], "trans": [{"from": "FIG-a34f2e28c559e82f", "to": "FIG-2684fed4f6e0d0e4", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
